<template>
  <div>
    <div v-show="false" ref="tourPurchasesFirstStep">
      <div class="tour-first-step-content">
        <v-icon size="90" class="mb-6">
          mdi-truck
        </v-icon>
        <h1>
          {{ getTranslatedText('tour.purchasesTour.firstStep.firstText') }}
        </h1>
        <h2>
          {{ getTranslatedText('tour.purchasesTour.firstStep.secondText') }}
        </h2>
      </div>
    </div>
    <div v-show="false" ref="tourPurchasesSecondStep">
      <div class="tour-third-step-content">
        <h2>
          {{ getTranslatedText('tour.purchasesTour.secondStep.firstText') }}
        </h2>
        <h3>
          {{ getTranslatedText('tour.purchasesTour.secondStep.secondText') }}
        </h3>
      </div>
    </div>
  </div>
</template>

<script>
import { mapState, mapGetters, mapActions } from 'vuex'

import purchasesTour from '@/config/tours/purchasesTour'
import USER_EVENTS from '@/config/events/databaseAPI/usersEvents'

import { getTranslatedText } from '@/tools/data'
import tourTrackTools from '@/tools/tourTrack'

import tourService from '@/services/renderer/tour'
import rendererEventsService from '@/services/renderer/rendererEvents'

import purchasesViewActions from '@/store/purchasesView/actions.types'
import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'

export default {
  name: 'VendorsViewTour',
  computed: {
    ...mapState('purchasesView', ['tourEnabled']),
    ...mapState('usersView', ['selectedUser']),
    ...mapGetters('suppliers', ['getFilteredSuppliers']),
  },
  methods: {
    getTranslatedText,
    ...mapActions('purchasesView', [purchasesViewActions.setTourEnabled]),
    ...mapActions('app', [appActions.setConfirmCancelTourDialogStatus]),
    ...mapActions('usersView', [usersViewActions.setSelectedUser]),
    createAndStartTour() {
      this.tour = tourService.createTour(this, purchasesTour.tourOptions)
      tourService.addSteps(this, purchasesTour.firstPartSteps)
      tourService.addCancelFunctionToSteps(this, this.confirmCancelTour)
      this.tour.steps[1].once('show', () => {
        setTimeout(
          () => document.getElementById('vendors-input-search').click(),
          400
        )
      })
      this.tour.steps[2].once('show', () => {
        setTimeout(
          () => document.getElementById('vendors-input-search').click(),
          400
        )
      })
      tourTrackTools.initTracks.call(this, 'Vendors')
      this.tour.on('cancel', () => {
        this.disabledVendorsTour()
      })
      this.tour.start()
    },
    confirmCancelTour() {
      this[appActions.setConfirmCancelTourDialogStatus]({
        isOpen: true,
        tour: this.tour,
      })
    },
    disabledVendorsTour() {
      const selectedUser = Object.assign(this.selectedUser)
      rendererEventsService.send(USER_EVENTS.channel, {
        event: USER_EVENTS.events.update.name,
        data: {
          userId: selectedUser.id,
          values: { vendors_tour_disabled: 1 },
        },
      })
      this[purchasesViewActions.setTourEnabled](false)
      selectedUser.vendorsTourDisabled = 1
      this[usersViewActions.setSelectedUser](selectedUser)
    },
  },
  watch: {
    getFilteredSuppliers: function(value) {
      if (this.tourEnabled) {
        const currentStep = this.tour.getCurrentStep().id
        if (currentStep === 'tourPurchasesSecondStep' && value.length !== 0)
          this.tour.next()
      }
    },
  },
  mounted() {
    this[purchasesViewActions.setTourEnabled](
      this.selectedUser.vendorsTourDisabled === 0
    )
    if (!this.tourEnabled) return
    this.createAndStartTour()
    this.$root.$on('vendor-added-purchases-tour', () => {
      const currentStep = this.tour.getCurrentStep().id
      if (this.tourEnabled && currentStep === 'tourPurchasesThirdStep') {
        setTimeout(() => {
          this.tour.next()
        }, 300)
      }
    })
    this.$root.$on('vendor-cancel-tour', () => {
      const currentStep = this.tour.getCurrentStep().id
      if (this.tourEnabled && currentStep === 'tourPurchasesFourthStep')
        this.tour.back()
    })
  },
  beforeDestroy() {
    this.$root.$off('vendor-added-purchases-tour')
    this.$root.$off('vendor-cancel-tour')
  },
}
</script>
