import { vendor as vendorMapper } from '@/config/storeMapper'

import { mapStoreObject } from '@/tools/data'
import {
  formatNumberFromDb,
  formatNumberToCurrency,
  formatNumberToDb,
} from '@/tools/numbersFormat'

import SingleEditDataWidget from '@/components/shared/SingleEditDataWidget'
import FrequencySelector from '@/components/VendorsView/VendorDetailDialog/FrequencySelector'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: [
    [
      {
        id: 'legalId',
        type: SingleEditDataWidget,
        value: state.vendor.tributaryId,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: 'vendorsView.dialogs.detail.fields.identification',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: 'field-width',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue =>
          methods.updateSelectedVendor({
            field: 'tributaryId',
            value: newValue,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.vendor.id,
            data: mapStoreObject(
              { tributaryId: state.vendor.tributaryId },
              vendorMapper,
              true
            ),
          })
        },
      },
      {
        id: 'sellerName',
        type: SingleEditDataWidget,
        value: state.vendor.sellerName,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: 'vendorsView.dialogs.detail.fields.name',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: 'field-width',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue =>
          methods.updateSelectedVendor({
            field: 'sellerName',
            value: newValue,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.vendor.id,
            data: mapStoreObject(
              { sellerName: state.vendor.sellerName },
              vendorMapper,
              true
            ),
          })
        },
      },
      {
        id: 'sellerPhone',
        type: SingleEditDataWidget,
        value: state.vendor.sellerPhone,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: 'vendorsView.dialogs.detail.fields.phone',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: 'field-width',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue =>
          methods.updateSelectedVendor({
            field: 'sellerPhone',
            value: newValue,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.vendor.id,
            data: mapStoreObject(
              { sellerPhone: state.vendor.sellerPhone },
              vendorMapper,
              true
            ),
          })
        },
      },
    ],
    [
      {
        id: 'daysSelector',
        type: FrequencySelector,
        label: 'vendorsView.dialogs.detail.fields.daysVisists',
        value: state.vendor.frequency.split(','),
        onInputChange: newValue => {
          let freq = state.vendor.frequency.split(',')
          let newFreq = ['0', '0', '0', '0', '0', '0', '0']
          newFreq.push(freq[7])
          newFreq.push(freq[8])
          newValue.forEach(value => {
            newFreq[value] = '1'
          })
          methods.updateSelectedVendor({
            field: 'frequency',
            value: newFreq.toString(),
          })
        },
        onFinishEdit: () => {
          methods.updateDatabase({
            id: state.vendor.id,
            data: mapStoreObject(
              { frequency: state.vendor.frequency },
              vendorMapper,
              true
            ),
          })
        },
      },
    ],
    [
      {
        id: 'debtLimit',
        type: SingleEditDataWidget,
        value: state.vendor.debtLimit,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        editTextType: 'number',
        label: 'vendorsView.dialogs.detail.fields.debtLimit',
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: 'field-width',
        textFormatter: value =>
          value === undefined || value === null || value.length < 1
            ? '-'
            : formatNumberToCurrency(value),
        numberFormatter: value => (value > 0 ? formatNumberFromDb(value) : ''),
        onInputChange: newValue =>
          methods.updateSelectedVendor({
            field: 'debtLimit',
            value: newValue > 0 ? formatNumberToDb(newValue) : 0,
          }),
        onInputFinishEdit: () => {
          methods.updateDatabase({
            id: state.vendor.id,
            data: mapStoreObject(
              {
                debtLimit:
                  state.vendor.debtLimit > 0 ? state.vendor.debtLimit : 0,
              },
              vendorMapper,
              true
            ),
          })
        },
      },
    ],
  ],
})

export default setConfig
