const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'vendorsView.dialogs.purchaseDraft.title',
    messages: ['vendorsView.dialogs.purchaseDraft.message'],
    acceptButtonText: 'vendorsView.dialogs.purchaseDraft.buttons.newPurchase',
    titleColor: 'textPrimary',
    height: 225,
    maxWidth: 500,
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: state.routeName,
        screen: 'PurchaseDraftDialog',
        name: 'Close dialog',
      })
      methods.closeDialog()
    },
    onClickAccept: () => methods.newPurchase(),
  },
})

export default setConfig
