import { getDayOfWeek, getDayOfMonth, getNow, addDays } from '@/tools/dates'

import VendorCard from '@/components/shared/VendorCard'

export const setConfig = (state, methods) => ({
  state,
  containerRef: 'vendors-view__list',
  title: 'vendorsView.list.title',
  titleClass: 'pl-2',
  icon: 'mdi-truck',
  sort: {
    by: [{ prop: 'name', text: 'vendorsView.list.sortBy.name' }],
    sortBy: 'name',
    sortDesc: false,
    iconColor: 'accent',
    customSort: methods.customSort,
  },
  columns: [
    {
      title: `${methods.context.$vuetify.lang.t(
        `$vuetify.vendorsView.list.columns.today`
      )}, ${methods.context.$vuetify.lang.t(
        `$vuetify.dates.dayOfWeek.${getDayOfWeek(getNow(false))}`
      )} ${getDayOfMonth(getNow())}, ${methods.context.$vuetify.lang.t(
        `$vuetify.vendorsView.list.visitYou`
      )}`,
      fetching: state.fetching,
      items: state.todayDeliveries,
      itemsPerColumn: 5,
      page: 1,
      currentCardComponent: state.currentCardComponent,
      cardComponents: {
        VendorCard: {
          component: VendorCard,
          cardHeight: 95,
          methods: {
            ...methods,
            onClick: vendor => methods.onClickCard(vendor),
            onDblClick: vendor => methods.onClickCard(vendor),
          },
          truncate: {
            lg: '50',
            xl: '100',
          },
        },
      },
      noDataMessage: {
        icon: 'mdi-cube-off-outline',
        messages: ['vendorsView.list.noData.noScheduledVisits'],
      },
    },
    {
      title: `${methods.context.$vuetify.lang.t(
        `$vuetify.vendorsView.list.columns.tomorrow`
      )}, ${methods.context.$vuetify.lang.t(
        `$vuetify.dates.dayOfWeek.${getDayOfWeek(addDays(getNow(), 1))}`
      )} ${getDayOfMonth(
        addDays(getNow(), 1)
      )}, ${methods.context.$vuetify.lang.t(
        `$vuetify.vendorsView.list.visitYou`
      )}`,
      fetching: state.fetching,
      items: state.tomorrowDeliveries,
      itemsPerColumn: 5,
      page: 1,
      currentCardComponent: state.currentCardComponent,
      cardComponents: {
        VendorCard: {
          component: VendorCard,
          cardHeight: 95,
          methods: {
            ...methods,
            onClick: vendor => methods.onClickCard(vendor),
            onDblClick: vendor => methods.onClickCard(vendor),
          },
          truncate: {
            lg: '50',
            xl: '100',
          },
        },
      },
      noDataMessage: {
        icon: 'mdi-cube-off-outline',
        messages: ['vendorsView.list.noData.noScheduledVisits'],
      },
    },
    {
      title: methods.context.$vuetify.lang.t(
        `$vuetify.vendorsView.list.columns.othersVendors`
      ),
      fetching: state.fetching,
      items: state.othersVendors,
      lastChild: {
        componentName: 'AddCustomVendor',
      },
      itemsPerColumn: 5,
      page: 1,
      currentCardComponent: state.currentCardComponent,
      cardComponents: {
        VendorCard: {
          component: VendorCard,
          cardHeight: 95,
          methods: {
            ...methods,
            onClick: vendor => methods.onClickCard(vendor),
            onDblClick: vendor => methods.onClickCard(vendor),
          },
          truncate: {
            lg: '50',
            xl: '100',
          },
        },
      },
      noDataMessage: {
        icon: 'mdi-plus-circle',
        messages: [
          'vendorsView.list.noData.firstMessage',
          'vendorsView.list.noData.secondMessage',
        ],
      },
    },
  ],
})

export default setConfig
