<template>
  <v-card-actions>
    <div>
      <v-btn
        v-if="!tourEnabled"
        color="error"
        ref="deleteVendorButton"
        @click="deleteVendor"
        v-track:click="{
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Delete vendor',
        }"
      >
        <v-icon color="white">mdi-delete-outline</v-icon>
        <FormattedText intl value="shared.delete" color="white" />
      </v-btn>
      <v-btn
        v-if="showPayDebtButton"
        color="secondary"
        ref="customerDetailPayDebtButton"
        @click="payDebt"
        v-track:click="{
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Settle debt',
        }"
      >
        <v-icon color="white">mdi-cash-refund</v-icon>
        <FormattedText
          intl
          value="customersView.customerDetails.payDebt"
          color="white"
        />
      </v-btn>
      <v-btn color="primary" id="add-new-purchase" @click="addPurchase">
        <v-icon>mdi-truck-fast</v-icon>
        <FormattedText
          intl
          value="vendorsView.dialogs.detail.buttons.newPurchase"
          color="white"
        />
      </v-btn>
      <DeleteVendorDialog v-if="deleteVendorDialog.isOpen" />
      <PurchaseDraftDialog v-if="purchaseDraftDialog.isOpen" />
      <SettleDebtDialog v-if="settleDebtDialog.isOpen" />
    </div>
    <div>
      <v-btn
        color="accent"
        @click="CloseDialog"
        v-track:click="{
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Close vendor details',
        }"
      >
        <v-icon>mdi-close-circle-outline</v-icon>
        <FormattedText intl value="close" color="white" />
      </v-btn>
    </div>
  </v-card-actions>
</template>

<script>
import { mapActions, mapState } from 'vuex'
import { isNil } from 'ramda'

import { testMode } from '@/config/env'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import DeleteVendorDialog from '@/components/VendorsView/VendorDetailDialog/Footer/DeleteVendorDialog'
import PurchaseDraftDialog from '@/components/VendorsView/VendorDetailDialog/Footer/PurchaseDraftDialog'
import SettleDebtDialog from '@/components/VendorsView/VendorDetailDialog/Footer/SettleDebtDialog'

export default {
  name: 'VendorFooter',
  components: {
    FormattedText,
    DeleteVendorDialog,
    PurchaseDraftDialog,
    SettleDebtDialog,
  },
  data() {
    return {
      addingPurchase: false,
    }
  },
  computed: {
    ...mapState('vendorsView', [
      'deleteVendorDialog',
      'addPurchaseDialog',
      'selectedVendor',
      'purchaseDraftDialog',
      'settleDebtDialog',
    ]),
    ...mapState('usersView', ['selectedUser']),
    ...mapState('purchasesView', ['tourEnabled']),
    showPayDebtButton() {
      return this.selectedVendor.debt > 0
    },
  },
  methods: {
    ...mapActions('vendorsView', [
      vendorsViewActions.setDeleteVendorDialogStatus,
      vendorsViewActions.toggleVendorDetailDialog,
      vendorsViewActions.togglePurchaseDraftDialog,
      vendorsViewActions.setSelectedVendor,
      vendorsViewActions.setSelectedSupplier,
      vendorsViewActions.toggleSettleDebtDialogStatus,
    ]),
    deleteVendor() {
      this[vendorsViewActions.setDeleteVendorDialogStatus](true)
    },
    addPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'VendorDetails',
        name: 'Create purchase',
      })
      const newPurchase = {
        vendorId: this.selectedVendor.id,
        status: 1,
        source: 1,
        promotion: 0,
        items: [],
        returnItems: [],
        cost: 0,
      }
      if (this.hasPurchaseInDraft() && !this.tourEnabled) {
        this.$track({
          type: 'system',
          action: 'create_purchase',
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Show draft purchase dialog',
        })
        this[vendorsViewActions.togglePurchaseDraftDialog]({
          purchase: newPurchase,
        })
        return
      }
      this.createPurchase(newPurchase)
    },
    hasPurchaseInDraft() {
      const lastPurchase = this.selectedVendor.purchases[0]
      if (isNil(lastPurchase)) return false
      return lastPurchase.status === '1' ? true : false
    },
    createPurchase(purchase) {
      if (this.addingPurchase) return
      this.addingPurchase = true
      this.$loading.show('createPurchase')
      rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
        event: PURCHASES_DB_API_EVENTS.events.add.name,
        data: {
          purchaseData: purchase,
        },
      })
      this[vendorsViewActions.toggleVendorDetailDialog]()
    },
    CloseDialog() {
      if (this.tourEnabled) this.$root.$emit('vendor-cancel-tour')
      this[vendorsViewActions.setSelectedSupplier](null)
      this[vendorsViewActions.setSelectedVendor](null)
      this[vendorsViewActions.toggleVendorDetailDialog]()
    },
    payDebt() {
      this[vendorsViewActions.toggleSettleDebtDialogStatus]()
    },
    async purchaseListener(event, payload) {
      const purchaseAddReplies = PURCHASES_DB_API_EVENTS.events.add.replies
      const replies = {
        [purchaseAddReplies.success]: () => {
          this.$track({
            type: 'system',
            action: 'add_purchase',
            category: 'Vendors',
            screen: 'VendorDetails',
            name: 'Go to purchase',
          })
          this.addingPurchase = false
        },
        [purchaseAddReplies.error]: () => (this.addingPurchase = false),
      }
      if (payload.event in replies) {
        this.$track({
          type: 'system',
          action: 'error',
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Error adding purchase',
        })
        replies[payload.event]()
      }
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseListener
    )
  },
}
</script>
