<template>
  <div class="fill-height">
    <PaginatedColumns :config="paginatedCardsConfig" />
    <VendorDetailDialog v-if="vendorDetailDialog.isOpen" />
    <VendorAddDialog v-if="addVendorDialog.isOpen" />
  </div>
</template>

<script>
import { isNil, values } from 'ramda'
import { mapActions, mapGetters, mapState } from 'vuex'

import { testMode } from '@/config/env'
import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'
import PAYABLES_DB_API_EVENTS from '@/config/events/databaseAPI/payablesEvents'

import { getDay, getNow } from '@/tools/dates'
import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import vendorsViewActions from '@/store/vendorsView/actions.types'
import vendorsActions from '@/store/vendors/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import appActions from '@/store/app/actions.types'

import setConfig from '@/components/VendorsView/VendorsList/config'
import VendorDetailDialog from '@/components/VendorsView/VendorDetailDialog'
import VendorAddDialog from '@/components/VendorsView/VendorAddDialog'
import PaginatedColumns from '@/components/shared/PaginatedColumns.vue'

export default {
  name: 'VendorsList',
  components: {
    VendorDetailDialog,
    VendorAddDialog,
    PaginatedColumns,
  },
  data() {
    return {
      todayDeliveries: [],
      tomorrowDeliveries: [],
      othersVendors: [],
      addingVendor: false,
    }
  },
  computed: {
    ...mapState('app', ['sidebarOpened']),
    ...mapState('vendors', ['data', 'fetching']),
    ...mapState('vendorsView', [
      'addVendorDialog',
      'vendorDetailDialog',
      'addPurchaseDialog',
      'selectedVendor',
    ]),
    ...mapState('purchasesView', ['tourEnabled']),
    ...mapGetters('vendors', ['getFilteredVendors']),
    ...mapGetters('suppliers', ['getFilteredSuppliers']),
    paginatedCardsConfig() {
      return setConfig(
        {
          todayDeliveries: this.todayDeliveries,
          tomorrowDeliveries: this.tomorrowDeliveries,
          othersVendors: this.othersVendors,
          sidebarOpened: this.sidebarOpened,
          currentCardComponent: 'VendorCard',
          fetching: this.fetching,
        },
        {
          context: this,
          onClickCard: this.onClickCard,
          customSort: this.customSort,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('app', values(appActions)),
    ...mapActions('vendorsView', values(vendorsViewActions)),
    ...mapActions('vendors', values(vendorsActions)),
    ...mapActions('usersView', values(usersViewActions)),
    resetList() {
      this.todayDeliveries = []
      this.tomorrowDeliveries = []
      this.othersVendors = []
    },
    processVendors() {
      this.resetList()
      this.getFilteredVendors.filter(vendor => {
        if (isNil(vendor.frequency)) {
          vendor.frequency = `0,0,0,0,0,0,0,1,${getNow(false)}`
        }
        const freq = vendor.frequency.split(',')
        // // Adapt start day of week from  English week to Spansih week
        const tomorrowDayOfWeek = getDay(getNow())
        const todayDayOfWeek =
          tomorrowDayOfWeek == 0 ? 6 : tomorrowDayOfWeek - 1
        if (freq[todayDayOfWeek] === '1' || freq[tomorrowDayOfWeek] === '1') {
          if (freq[todayDayOfWeek] === '1') this.todayDeliveries.push(vendor)
          if (freq[tomorrowDayOfWeek] === '1')
            this.tomorrowDeliveries.push(vendor)
        } else {
          this.othersVendors.push(vendor)
        }
      })
      this.othersVendors = this.othersVendors.concat(this.getFilteredSuppliers)
    },
    customSort(items, index, isDesc) {
      return items.sort((a, b) => {
        if (a.isSupplierAdded !== b.isSupplierAdded) return 1
        return !isDesc[0]
          ? a.name.localeCompare(b.name)
          : b.name.localeCompare(a.name)
      })
    },
    onClickCard(item) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'VendorCard',
        name: item.isSupplierAdded ? 'Open vendor details' : 'Add new vendor',
      })
      item.isSupplierAdded
        ? this.openVendorDialog(item)
        : this.createVendor(item)
    },
    openVendorDialogIfRouteRequires() {
      if (!this.$route.query.vendorId) return
      const vendorFound = this.data.vendors.find(
        vendor => vendor.id === Number(this.$route.query.vendorId)
      )
      if (!vendorFound) return
      this.openVendorDialog(vendorFound)
      this.$router.replace({
        query: {},
      })
    },
    openVendorDialog(vendor) {
      this[vendorsViewActions.setSelectedVendor](vendor)
      this[vendorsViewActions.toggleVendorDetailDialog]()
      if (this.tourEnabled) {
        setTimeout(() => {
          const tab = document.querySelectorAll('[href="#tab-1"]')[0]
          tab.click()
          this.$root.$emit('vendor-added-purchases-tour')
        }, 100)
      }
    },
    createVendor(supplier) {
      if (this.addingVendor) return
      this.addingVendor = true
      const { id, type, hasLogo, name } = supplier
      const today = getNow(false)
      let vendor = {
        supplierId: id,
        supplierType: type,
        hasLogo: hasLogo,
        name: name,
        sellerName: '',
        sellerPhone: '',
        tributaryId: '',
        frequency: `0,0,0,0,0,0,0,1,${today}`,
        presaleDays: 0,
        debtLimit: null,
      }
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.add.name,
        data: vendor,
      })
    },
    addVendorListener(event, payload) {
      const addReplies = VENDORS_DB_API_EVENTS.events.add.replies
      const replies = {
        [`${addReplies.success}`]: () => {
          this.$track({
            type: 'system',
            action: 'add_vendor',
            category: 'Vendors',
            screen: 'VendorCard',
            name: 'Open vendor details',
          })
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
          this.addingVendor = false
          this[appActions.addPendingSyncOperation]()
          notificationsService.showSuccess(
            'notification.vendors.addSuccess',
            this.$vuetify.lang
          )
          this.openVendorDialog({ ...payload.data, purchases: [] })
          this.$root.$emit('reset')
          this[vendorsViewActions.setVendorSearchTerm](null)
          setTimeout(() => {
            const tab = document.querySelectorAll('[href="#tab-1"]')[0]
            tab.click()
          }, 100)
        },
        [`${addReplies.error}`]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Vendors',
            screen: 'VendorCard',
            name: 'Error adding new vendor',
          })
          this.addingVendor = false
          notificationsService.showError(
            'notification.vendors.addError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    updateVendorListener(event, payload) {
      const updateReplies = VENDORS_DB_API_EVENTS.events.update.replies
      const replies = {
        [`${updateReplies.success}`]: () => {
          this[vendorsActions.updateVendor](payload.data)
          this[vendorsActions.editVendorField](this.selectedVendor)
          this[appActions.addPendingSyncOperation]()
          notificationsService.showSuccess(
            'notification.vendors.updateSuccess',
            this.$vuetify.lang
          )
        },
        [`${updateReplies.error}`]: () =>
          notificationsService.showError(
            'notification.vendors.updateError',
            this.$vuetify.lang
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    deleteVendorListener(event, payload) {
      const deleteReplies = VENDORS_DB_API_EVENTS.events.delete.replies
      const replies = {
        [`${deleteReplies.success}`]: () => {
          this[vendorsActions.deleteVendor]({ id: payload.data.vendorId })
          this[vendorsViewActions.toggleVendorDetailDialog]()
          this[vendorsViewActions.setDeleteVendorDialogStatus](false)
          this[appActions.addPendingSyncOperation]()
          notificationsService.showSuccess(
            'notification.vendors.deleteSuccess',
            this.$vuetify.lang
          )
        },
        [`${deleteReplies.error}`]: () =>
          notificationsService.showError(
            'notification.vendors.deleteError',
            this.$vuetify.lang
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
    purchaseOperationsListener(event, payload) {
      const events = PURCHASES_DB_API_EVENTS.events
      const finishPurchaseReplies =
        PURCHASES_DB_API_EVENTS.events.finishPurchase.replies
      const replies = {
        [events.delete.replies.success]: () => {
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
        },
        [events.add.replies.success]: () => {
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
          setTimeout(() => {
            this.$loading.hide()
            this.$router.push({ path: '/app/vendors/purchases' })
          }, 700)
        },
        [events.repeatPurchase.replies.success]: () => {
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
          setTimeout(() => {
            this.$loading.hide()
            this.$router.push({ path: '/app/vendors/purchases' })
          }, 700)
        },
        [events.add.replies.error]: () =>
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          ),
        [`${finishPurchaseReplies.error}`]: () => {
          this.$loading.hide()
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    entitiesListener(event, payload) {
      const getAllReplies = ENTITIES_EVENTS.events.getAllByEntities.replies
      const replies = {
        [`${getAllReplies.success}-fetchVendors`]: async () => {
          await this[vendorsActions.setVendors](payload.data)
          if (isNil(this.selectedVendor)) return
          const vendorUpdated = this.data.vendors.find(
            ({ id }) => id === this.selectedVendor.id
          )
          this[vendorsViewActions.setSelectedVendor](vendorUpdated)
        },
        [`${getAllReplies.error}-fetchVendors`]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Vendors',
            screen: 'VendorsList',
            name: 'Error fetching vendors',
          })
          this[vendorsActions.setVendorsError](payload.data)
          this[vendorsActions.setVendorsFetching](false)
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    payablesListener(event, payload) {
      const events = PAYABLES_DB_API_EVENTS.events
      const replies = {
        [events.add.replies.success]: () => {},
        [events.add.replies.error]: () =>
          notificationsService.showError(
            'notification.payables.addPayableError',
            this.$vuetify.lang
          ),
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  watch: {
    getFilteredVendors: {
      deep: true,
      handler() {
        this.processVendors()
      },
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.addVendorListener
    )
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.updateVendorListener
    )
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.deleteVendorListener
    )
    rendererEventsService.subscribe(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOperationsListener
    )
    rendererEventsService.subscribe(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    rendererEventsService.subscribe(
      PAYABLES_DB_API_EVENTS.replyChannel,
      this.payablesListener
    )
  },
  beforeMount() {
    this.openVendorDialogIfRouteRequires()
    this.$watch(
      () => this.$route.query,
      () => {
        this.openVendorDialogIfRouteRequires()
      }
    )
  },
  mounted() {
    this[vendorsActions.setVendorsFetching](true)
    rendererEventsService.send(ENTITIES_EVENTS.channel, {
      event: ENTITIES_EVENTS.events.getAllByEntities.name,
      data: {
        entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
        replyName: 'fetchVendors',
      },
    })
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.addVendorListener
    )
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.updateVendorListener
    )
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.deleteVendorListener
    )
    rendererEventsService.removeListener(
      PURCHASES_DB_API_EVENTS.replyChannel,
      this.purchaseOperationsListener
    )
    rendererEventsService.removeListener(
      ENTITIES_EVENTS.replyChannel,
      this.entitiesListener
    )
    rendererEventsService.removeListener(
      PAYABLES_DB_API_EVENTS.replyChannel,
      this.payablesListener
    )
  },
}
</script>
