<template>
  <v-card
    flat
    color="cardBackgroundSecondary"
    class="rounded-lg py-3 px-4 mb-2 d-flex justify-space-between align-center"
  >
    <div class="d-flex flex-column">
      <FormattedText
        :value="formatDeliveryDate(purchase.delivery_date)"
        type="text-h6"
      />
      <v-chip
        v-if="purchase.hasPromotion"
        small
        color="error"
        label
        class="align-self-start"
      >
        <v-icon small class="mr-1">mdi-sale</v-icon>
        {{ getTranslatedText('vendorsView.dialogs.detail.withPromotion') }}
      </v-chip>
    </div>
    <div class="d-flex text-center align-center">
      <div>
        <FormattedText
          :value="formatNumberFromDbToCurrency(cost)"
          type="text-h6"
        />
        <v-tooltip left color="vendorPrimary" v-if="hasPayable(purchase._id)">
          <template v-slot:activator="{ on, attrs }">
            <div v-bind="attrs" v-on="on">
              <FormattedText
                :value="formatNumberFromDbToCurrency(getDebt(purchase._id))"
                type="subtitle-1"
                :color="isSettled ? 'textPrimary' : 'vendorDebt'"
                :className="isSettled ? 'text-decoration-line-through' : ''"
              />
            </div>
          </template>
          <span>
            {{ getTranslatedText('vendorsView.dialogs.detail.debtToPay') }}
          </span>
        </v-tooltip>
      </div>
      <v-btn
        color="primary"
        icon
        class="ml-4"
        elevation="0"
        v-if="purchase.status === '1'"
        @click="edit()"
        v-track:click="{
          category: 'Vendors',
          screen: 'VendorDetails',
          name: 'Edit purchase',
        }"
      >
        <v-icon>mdi-pencil</v-icon>
      </v-btn>
      <ButtonDropdown
        v-else
        fab
        depressed
        dark
        small
        transparent
        class="ml-2"
        icon="mdi-dots-vertical"
        color="textPrimary"
        listItemType="TextListItem"
        :items="purchaseOptions"
      />
    </div>
  </v-card>
</template>

<script>
import { mapState, mapActions } from 'vuex'
import { isNil } from 'ramda'

import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import { idOperations } from '@/config/cashOperationsVariables'

import { formatDate, getDayOfWeek } from '@/tools/dates'
import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import ButtonDropdown from '@/components/shared/ButtonDropdown'

export default {
  name: 'PurchaseCard',
  components: { FormattedText, ButtonDropdown },
  props: {
    purchase: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      purchaseOptions: [
        {
          icon: 'mdi-eye',
          text: 'vendorsView.dialogs.detail.lastOrders.viewOrder',
          action: this.lookPurchase,
        },
        {
          icon: 'mdi-refresh',
          text: 'vendorsView.dialogs.detail.lastOrders.repeatOrder',
          action: this.repeatPurchase,
        },
      ],
    }
  },
  computed: {
    ...mapState('vendorsView', ['selectedVendor']),
    isSettled() {
      const playable = this.selectedVendor.payables.find(
        payable => payable.purchase_id === this.purchase._id
      )
      return playable.paid === 1
    },
    cost() {
      if (this.purchase.status === '1') {
        return this.purchase.cost - this.purchase.promotion
      }
      return this.purchase.cost
    },
  },
  methods: {
    getTranslatedText,
    formatNumberFromDbToCurrency,
    ...mapActions('vendorsView', [
      vendorsViewActions.toggleRepeatPurchaseConfirmDialog,
    ]),
    formatDeliveryDate(deliveryDate) {
      const dayOfWeek = this.getTranslatedText(
        `dates.dayOfWeek.${getDayOfWeek(deliveryDate)}`
      )
      return `${dayOfWeek}, ${formatDate(deliveryDate)}`
    },
    edit() {
      this.$router.push({ path: '/app/vendors/purchases' })
    },
    lookPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'VendorDetails',
        name: 'View purchase',
      })
      rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
        event:
          CASH_OPERATIONS_DB_API_EVENTS.events.getByOperationTypeAndRelatedId
            .name,
        data: {
          type: this.hasPayable(this.purchase._id)
            ? idOperations.ID_OPERATION_CREDIT_PURCHASE
            : idOperations.ID_OPERATION_CASH_PURCHASE,
          relatedId: this.purchase._id,
        },
      })
    },
    hasPayable(purchaseId) {
      if (isNil(this.selectedVendor.payables)) return false
      return !isNil(
        this.selectedVendor.payables.find(
          payable => payable.purchase_id === purchaseId
        )
      )
    },
    getDebt(purchaseId) {
      const payable = this.selectedVendor.payables.find(
        payable => payable.purchase_id === purchaseId
      )
      return payable.paid === 1
        ? payable.amount
        : payable.amount - payable.settled
    },
    repeatPurchase() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'VendorDetails',
        name: 'Repeat purchase',
      })
      this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog](this.purchase)
    },
  },
}
</script>
