<template>
  <div>
    <DialogCard :config="componentConfig.dialogData">
      <Form :config="componentConfig" />
      <template v-slot:footer>
        <MultipleButtons :config="componentConfig.multipleButtons" />
      </template>
    </DialogCard>
    <ExternalCashRegisterInfo @userHasBeenInformed="settleDebt(true)" />
  </div>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'

import { cleanObjectObserver } from '@/tools/data'
import {
  formatNumberFromDb,
  formatNumberToCurrency,
  formatNumberToDb,
} from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import usersViewActions from '@/store/usersView/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'
import vendorsActions from '@/store/vendors/actions.types'

import setDialogConfig from '@/components/VendorsView/VendorDetailDialog/Footer/SettleDebtDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import MultipleButtons from '@/components/shared/MultipleButtons'
import ExternalCashRegisterInfo from '@/components/shared/ExternalCashRegisterInfo'

export default {
  name: 'SettleDebtDialog',
  components: { ExternalCashRegisterInfo, MultipleButtons, DialogCard, Form },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      payDebt: false,
    }
  },
  computed: {
    ...mapState('vendorsView', [
      'vendorDetailDialog',
      'settleDebtDialog',
      'selectedVendor',
    ]),
    ...mapState('usersView', ['selectedUser', 'estimatedCash']),
    componentConfig() {
      return setDialogConfig(
        {
          opened: this.settleDebtDialog.isOpen,
          inputs: this.inputs,
          v: this.$v.inputs,
          vendor: this.selectedVendor,
        },
        {
          closeDialog: this.closeDialog,
          showInfoDialog: this.showInfoDialog,
          track: this.$track,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.addPendingSyncOperation,
      appActions.toggleExternalCashRegisterInfoDialog,
    ]),
    ...mapActions('vendorsView', [
      vendorsViewActions.toggleSettleDebtDialogStatus,
      vendorsViewActions.toggleVendorDetailDialog,
    ]),
    ...mapActions('usersView', [usersViewActions.setUserEstimatedCash]),
    ...mapActions('vendors', [vendorsActions.settleCreditPurchase]),
    setProperties() {
      this.componentConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators)
          this.$set(this.validators.inputs, field.id, {
            ...cleanObjectObserver(field.validators),
          })
      })
    },
    closeDialog() {
      Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$reset())
      Object.keys(this.inputs).forEach(key => (this.inputs[key] = ''))
      this[vendorsViewActions.toggleSettleDebtDialogStatus]()
    },
    getEstimatedCash() {
      const stateEstimatedCash =
        this.estimatedCash === null || this.estimatedCash === undefined
          ? 0
          : this.estimatedCash
      return formatNumberToDb(stateEstimatedCash)
    },
    showInfoDialog(isFromExternalCashRegister = false) {
      if (this.payDebt) return
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      if (!isFromExternalCashRegister) {
        this.$track({
          type: 'interaction',
          action: 'click',
          category: 'Vendors',
          screen: 'SettleDebtDialog',
          name: 'Pay with cash register',
        })
        this.settleDebt(isFromExternalCashRegister)
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'SettleDebtDialog',
        name: 'Pay with external cash',
      })
      this[appActions.toggleExternalCashRegisterInfoDialog](true)
    },
    settleDebt(isFromExternalCashRegister) {
      this.payDebt = true
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.settleGeneralDebt.name,
        data: {
          vendor: this.selectedVendor,
          amount: formatNumberToDb(this.inputs.settleGeneralDebtAmount),
          user: this.selectedUser.id,
          estimatedCash: this.getEstimatedCash(),
          isFromExternalCashRegister,
        },
      })
    },
    async vendorsListener(event, payload) {
      const settleGeneralDebtReplies =
        VENDORS_DB_API_EVENTS.events.settleGeneralDebt.replies
      const replies = {
        [settleGeneralDebtReplies.success]: () => {
          this.$track({
            type: 'system',
            action: 'settle_debt',
            category: 'Vendors',
            screen: 'SettleDebtDialog',
            name: 'Close dialog',
          })
          this.onGeneralDebtSettled(payload.data)
        },
        [settleGeneralDebtReplies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Vendors',
            screen: 'SettleDebtDialog',
            name: 'Error settling debt',
          })
          this.payDebt = false
          notificationsService.showError(
            'vendorsView.dialogs.settleDebtDialog.errorSettlingDebt',
            this.$vuetify.lang
          )
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    onGeneralDebtSettled(data) {
      this[appActions.addPendingSyncOperation]()
      this[vendorsActions.settleCreditPurchase](data.vendor)
      this[usersViewActions.setUserEstimatedCash](
        formatNumberFromDb(data.estimatedCash)
      )
      this.payDebt = false
      notificationsService.showSuccess(
        'vendorsView.dialogs.settleDebtDialog.debtSettled',
        this.$vuetify.lang,
        {},
        [formatNumberToCurrency(this.inputs.settleGeneralDebtAmount)]
      )
      this.closeDialog()
      this[vendorsViewActions.toggleVendorDetailDialog]()
    },
  },
  validations() {
    return this.validators
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsListener
    )
  },
  mounted() {
    this.setProperties()
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsListener
    )
  },
}
</script>
