<template>
  <v-container fluid class="container-view" id="vendors-view">
    <!-- View toolbar  -->
    <v-row no-gutters>
      <v-col
        class="container-view__filter-toolbar px-5 pt-6"
        id="vendors-view__filter-toolbar"
      >
        <VendorsToolbar />
      </v-col>
    </v-row>
    <!-- List view -->
    <v-row no-gutters>
      <v-col
        class="container-view__list"
        id="vendors-view__list"
        :style="{
          height: `calc(100vh - ${getVendorsListStyles}px)`,
        }"
      >
        <VendorsList />
      </v-col>
    </v-row>
    <VendorsViewTour v-if="!$route.query.fromTour" />
  </v-container>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { getAppLayoutHeaderAndFooterHeight } from '@/tools/view'

import vendorsActions from '@/store/vendors/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'

import VendorsToolbar from '@/components/VendorsView/VendorsToolbar'
import VendorsList from '@/components/VendorsView/VendorsList'
import VendorsViewTour from '@/components/VendorsView/VendorsViewTour'

export default {
  name: 'VendorsView',
  components: { VendorsToolbar, VendorsList, VendorsViewTour },
  data() {
    return {
      layoutCommonElementsHeight: 0,
    }
  },
  computed: {
    ...mapState('usersView', ['selectedUser']),
    ...mapState('vendorsView', ['addVendorDialog', 'vendorDetailDialog']),
    getVendorsListStyles() {
      return this.layoutCommonElementsHeight
    },
  },
  methods: {
    ...mapActions('vendors', [
      vendorsActions.setVendors,
      vendorsActions.setVendorsError,
      vendorsActions.setVendorsFetching,
    ]),
    ...mapActions('vendorsView', [
      vendorsViewActions.setSelectedVendor,
      vendorsViewActions.setSelectedSupplier,
      vendorsViewActions.toggleAddVendorDialog,
      vendorsViewActions.toggleVendorDetailDialog,
    ]),
    getLayoutHeight() {
      const layoutComponentsHeight = getAppLayoutHeaderAndFooterHeight(
        'vendors-view'
      )
      const vendorsViewToolbar = document.getElementById(
        'vendors-view__filter-toolbar'
      ).offsetHeight
      this.layoutCommonElementsHeight =
        layoutComponentsHeight + vendorsViewToolbar
    },
  },
  mounted() {
    this.getLayoutHeight()
  },
  destroyed() {
    if (this.addVendorDialog.isOpen) {
      this[vendorsViewActions.toggleAddVendorDialog]()
      this[vendorsViewActions.setSelectedSupplier](null)
      this[vendorsViewActions.setSelectedVendor](null)
    }
    if (this.vendorDetailDialog.isOpen)
      this[vendorsViewActions.toggleVendorDetailDialog]()
  },
}
</script>

<style lang="scss" scoped>
.container-view {
  height: 100%;
  .container-view__filter-toolbar {
    background-color: var(--v-mainBackground-base);
  }
  .container-view__list {
    width: 100%;
  }
}
</style>
