<template>
  <div class="d-flex flex-column">
    <FormattedText
      intl
      :value="label"
      type="text-subtitle-2"
      :class="!reverse ? 'label-padding' : ''"
    />
    <div class="mt-2">
      <v-btn-toggle
        v-model="value"
        tile
        color="daySelected"
        multiple
        @change="daySelected"
      >
        <v-btn>
          <FormattedText intl value="dates.shortWeek.monday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.tuesday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.wednesday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.thursday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.friday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.saturday" />
        </v-btn>
        <v-btn>
          <FormattedText intl value="dates.shortWeek.sunday" />
        </v-btn>
      </v-btn-toggle>
    </div>
    <div class="mt-4" v-if="config.widget">
      <RadioButtonGroupWidget :config="config.widget" :values="frequency" />
    </div>
  </div>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'
import RadioButtonGroupWidget from '@/components/shared/RadioButtonGroupWidget'

export default {
  name: 'FrequencySelector',
  components: {
    FormattedText,
    RadioButtonGroupWidget,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      label: this.config.label,
      reverse: this.config.reverse,
    }
  },
  computed: {
    frequency() {
      return this.config.value[7]
    },
    value: {
      get() {
        const daysOfVisits = this.config.value.slice(0, 7)
        let days = []
        daysOfVisits.forEach((data, index) => {
          if (data == 1) days.push(index)
        })
        return days
      },
      set(newValue) {
        return this.config.onInputChange(newValue)
      },
    },
  },
  methods: {
    daySelected() {
      this.config.onFinishEdit()
    },
  },
}
</script>
