<template>
  <v-dialog
    v-model="addVendorDialog.isOpen"
    :overlay-opacity="0.15"
    content-class="default-dialog"
    max-width="600px"
    @click:outside="closeDialog"
  >
    <v-card flat :height="660" color="cardBackgroundPrimary">
      <Header />
      <v-card-text>
        <div class="d-flex flex-column">
          <div
            v-for="(row, index) in widgetConfig.singleWidgets"
            :key="index"
            class="mb-3"
          >
            <div>
              <div v-for="widget in row" :key="widget.id">
                <component
                  :is="widget.type"
                  :config="widget"
                  :class="widget.extraClasses"
                  v-if="widget.visible"
                />
              </div>
            </div>
          </div>
        </div>
      </v-card-text>
      <v-card-actions>
        <v-spacer />
        <div>
          <v-btn color="accent" @click="closeDialog()" ref="cancelButton">
            <FormattedText
              intl
              value="shared.cancel"
              color="white"
              class="button-text"
            />
          </v-btn>
          <v-btn
            color="primary"
            @click="addVendor()"
            ref="saveButton"
            :disabled="nameEmpty"
            v-track:click="{
              category: 'Vendors',
              screen: 'CreateVendorDialog',
              name: 'Create vendor',
            }"
          >
            <FormattedText
              intl
              value="shared.accept"
              color="white"
              class="button-text"
            />
          </v-btn>
        </div>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>

<script>
import { values, isEmpty } from 'ramda'
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'

import { getTranslatedText } from '@/tools/data'
import { getNow } from '@/tools/dates'
import { formatNumberToDb } from '@/tools/numbersFormat'

import rendererEventsService from '@/services/renderer/rendererEvents'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import Header from '@/components/VendorsView/VendorDetailDialog/Header'
import FormattedText from '@/components/shared/FormattedText'
import setConfig from '@/components/VendorsView/VendorAddDialog/config.js'

export default {
  name: 'VendorAddDialog',
  components: { Header, FormattedText },
  data() {
    return {
      addingVendor: false,
    }
  },
  computed: {
    ...mapState('vendorsView', [
      'addVendorDialog',
      'selectedSupplier',
      'selectedVendor',
    ]),
    nameEmpty() {
      return isEmpty(this.selectedVendor.name)
    },
    widgetConfig() {
      return setConfig(
        {
          vendor: this.selectedVendor,
        },
        {
          getTranslatedText: this.getTranslatedText,
          updateSelectedVendor: this[
            vendorsViewActions.updateSelectedVendorField
          ],
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('vendorsView', values(vendorsViewActions)),
    closeDialog() {
      this[vendorsViewActions.setSelectedSupplier](null)
      this[vendorsViewActions.setSelectedVendor](null)
      this[vendorsViewActions.toggleAddVendorDialog]()
    },
    addVendor() {
      if (this.addingVendor) return
      this.addingVendor = true
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.add.name,
        data: {
          ...this.selectedVendor,
          debtLimit: formatNumberToDb(this.selectedVendor.debtLimit),
        },
      })
      this.closeDialog()
    },
    createTemporalVendor() {
      const { id, type, hasLogo, name } = this.selectedSupplier
      const today = getNow(false)
      let vendor = {
        supplierId: id,
        supplierType: type,
        hasLogo: hasLogo,
        name: name,
        sellerName: '',
        sellerPhone: '',
        tributaryId: '',
        frequency: `0,0,0,0,0,0,0,1,${today}`,
        presaleDays: 0,
        debtLimit: null,
      }
      this[vendorsViewActions.setSelectedVendor](vendor)
    },
    async vendorListener(event, payload) {
      const vendorAddReplies = VENDORS_DB_API_EVENTS.events.add.replies
      const replies = {
        [vendorAddReplies.success]: () => {
          this.$track({
            type: 'system',
            action: 'create_vendor',
            category: 'Vendors',
            screen: 'CreateVendorDialog',
            name: 'Add new vendor',
          })
          this.addingVendor = false
        },
        [vendorAddReplies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Vendors',
            screen: 'CreateVendorDialog',
            name: 'Error creating vendor',
          })
          this.addingVendor = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    this.createTemporalVendor()
    if (testMode) return
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorListener
    )
  },
}
</script>
