<template>
  <DialogCard :config="dialogConfig.dialogData" />
</template>

<script>
import { mapState, mapActions } from 'vuex'

import { testMode } from '@/config/env'
import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'

import rendererEventsService from '@/services/renderer/rendererEvents'

import vendorsViewActions from '@/store/vendorsView/actions.types'
import vendorsActions from '@/store/vendors/actions.types'

import setDialogConfig from '@/components/VendorsView/VendorDetailDialog/Footer/DeleteVendorDialog/config'
import DialogCard from '@/components/shared/DialogCard'

export default {
  name: 'DeleteCustomerDialog',
  components: { DialogCard },
  data() {
    return {
      vendorRemove: false,
    }
  },
  computed: {
    ...mapState('vendorsView', ['deleteVendorDialog', 'selectedVendor']),
    dialogConfig() {
      return setDialogConfig(
        {
          opened: this.deleteVendorDialog.isOpen,
        },
        {
          closeDialog: this.closeDialog,
          deleteVendor: this.removeVendor,
        }
      )
    },
  },
  methods: {
    ...mapActions('vendorsView', [
      vendorsViewActions.setDeleteVendorDialogStatus,
      vendorsViewActions.toggleVendorDetailDialog,
    ]),
    ...mapActions('vendors', [vendorsActions.deleteVendor]),
    closeDialog() {
      this[vendorsViewActions.setDeleteVendorDialogStatus](false)
    },
    removeVendor() {
      if (this.vendorRemove) return
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'DeleteVendorDialog',
        name: 'Confirm delete vendor',
      })
      this.vendorRemove = true
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.delete.name,
        data: this.selectedVendor,
      })
    },
    async vendorsListener(event, payload) {
      const deleteVendorReplies = VENDORS_DB_API_EVENTS.events.delete.replies
      const replies = {
        [deleteVendorReplies.success]: () => {
          this.$track({
            type: 'system',
            action: 'vendor_delete',
            category: 'Vendors',
            screen: 'DeleteVendorDialog',
            name: 'Close vendor dialog',
          })
          this.vendorRemove = false
        },
        [deleteVendorReplies.error]: () => {
          this.$track({
            type: 'system',
            action: 'error',
            category: 'Vendors',
            screen: 'DeleteVendorDialog',
            name: 'Error deleting vendor',
          })
          this.vendorRemove = false
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      VENDORS_DB_API_EVENTS.replyChannel,
      this.vendorsListener
    )
  },
}
</script>
