<template>
  <div class="d-flex flex-column">
    <section
      class="d-flex justify-space-between paginated-card__header pb-6 px-3"
    >
      <div class="d-flex align-center paginated-title">
        <v-icon color="primary" large>{{ config.icon }}</v-icon>
        <FormattedText
          intl
          type="text-h6"
          color="textPrimary"
          :value="config.title"
          :class="config.titleClass ? config.titleClass : ''"
        />
      </div>
      <div class="d-flex align-center paginated-card__header__controls">
        <v-select
          v-if="config.sort"
          v-model="sortBy"
          :items="config.sort.by"
          :item-text="item => getTranslatedText(item.text)"
          :menu-props="{ button: true, offsetY: true }"
          item-value="prop"
          :placeholder="getTranslatedText('shared.sortBy')"
          class="paginated-card__header__controls__sort-selector custom-text-field px-4"
          filled
          rounded
          hide-details
        />
        <Button
          v-if="config.sort"
          :color="config.sort.iconColor"
          dark
          tooltipPosition="bottom"
          fab
          small
          depressed
          :icon="sortDesc ? 'mdi-sort-descending' : 'mdi-sort-ascending'"
          @click="onSortButtonClick"
          v-track:click="{
            category: $route.name,
            screen: 'PaginatedColumns',
            name: 'Sort direction',
          }"
        />
      </div>
    </section>
    <section
      class="column-height d-flex justify-space-around"
      id="columns-container"
    >
      <div
        v-for="(column, index) in config.columns"
        :key="index"
        class="column"
      >
        <ColumnPaginatedCard
          :config="column"
          :sortDesc="sortDesc"
          :customSort="customSort"
        />
      </div>
    </section>
  </div>
</template>

<script>
import { getTranslatedText } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import Button from '@/components/shared/CustomButton'
import ColumnPaginatedCard from '@/components/shared/ColumnPaginatedCard.vue'

export default {
  name: 'PaginatedColumns',
  components: { FormattedText, ColumnPaginatedCard, Button },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      sortBy: this.config.sort ? this.config.sort.sortBy : null,
      sortDesc: this.config.sort ? this.config.sort.sortDesc : null,
      customSort: this.config.sort.customSort,
    }
  },
  methods: {
    getTranslatedText,
    onSortButtonClick() {
      return (this.sortDesc = !this.sortDesc)
    },
  },
}
</script>

<style lang="scss" scoped>
.paginated-card__header {
  min-height: 90px;
}
.paginated-card__header__controls {
  .paginated-card__header__controls__sort-selector {
    width: 250px;
  }
}
.column-height {
  height: calc(100vh - 270px);
}
.column {
  width: calc(100% / 3);
}
</style>
