<template>
  <div v-if="selectedVendor.purchases.length > 0 && !tourEnabled" class="mt-6">
    <ScrollContainer height="355px" max-height="355px">
      <PurchaseCard
        v-for="purchase in selectedVendor.purchases"
        :key="purchase._id + 12"
        :purchase="purchase"
      />
    </ScrollContainer>
    <OperationDetail v-if="operationDetailDialog.isOpen" />
    <RepeatPurchaseConfirmDialog v-if="repeatPurchaseConfirmDialog.isOpen" />
  </div>
  <AlertNoDataToShow icon="mdi-dolly" v-else />
</template>

<script>
import { mapState } from 'vuex'

import PurchaseCard from '@/components/shared/PurchaseCard.vue'
import OperationDetail from '@/components/OperationsView/OperationDetail'
import RepeatPurchaseConfirmDialog from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab/RepeatPurchaseConfirmDialog'
import AlertNoDataToShow from '@/components/shared/AlertNoDataToShow'
import ScrollContainer from '@/components/shared/ScrollContainer'

export default {
  name: 'LastOrdersTab',
  components: {
    ScrollContainer,
    AlertNoDataToShow,
    PurchaseCard,
    OperationDetail,
    RepeatPurchaseConfirmDialog,
  },
  computed: {
    ...mapState('vendorsView', [
      'selectedVendor',
      'repeatPurchaseConfirmDialog',
    ]),
    ...mapState('operationsView', ['operationDetailDialog']),
    ...mapState('purchasesView', ['tourEnabled']),
    scrollOps() {
      return {
        rail: {
          gutterOfSide: '-5px',
        },
        scrollPanel: {
          scrollingX: false,
        },
      }
    },
  },
}
</script>
