const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-alert-circle',
    title: 'vendorsView.dialogs.deleteVendor.title',
    messages: ['vendorsView.dialogs.deleteVendor.message'],
    titleColor: 'textPrimary',
    height: 225,
    maxWidth: 500,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.deleteVendor(),
  },
})

export default setConfig
