<template>
  <div v-show="showAddCustomVendorButton" class="text-center">
    <FormattedText
      intl
      type="text-h6"
      color="textPrimary"
      value="vendorsView.list.addCustomVendorText"
    />
    <v-btn
      text
      color="primary"
      v-track:click="{
        category: 'Vendors',
        screen: 'PaginatedColumns',
        name: 'Create vendor',
      }"
      @click="createCustomVendor"
    >
      <FormattedText
        intl
        type="text-h6"
        color="primary"
        value="vendorsView.list.addCustomVendorBtnText"
        class="text-decoration-underline"
      />
    </v-btn>
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AddCustomVendor',
  components: { FormattedText },
  computed: {
    ...mapState('purchasesView', ['tourEnabled']),
    showAddCustomVendorButton() {
      return !this.tourEnabled
    },
  },
  methods: {
    ...mapActions('vendorsView', [
      vendorsViewActions.setSelectedSupplier,
      vendorsViewActions.toggleAddVendorDialog,
    ]),
    createCustomVendor() {
      this[vendorsViewActions.setSelectedSupplier]({
        id: 0,
        hasLogo: 0,
        type: 1,
        name: '',
        nit: '',
      })
      this[vendorsViewActions.toggleAddVendorDialog]()
    },
  },
}
</script>
