<template>
  <v-data-iterator
    :items="config.items"
    :items-per-page.sync="itemsPerColumn"
    :loading="config.fetching"
    :page.sync="page"
    :customSort="customSort"
    :sort-desc="sortDesc"
    class="d-flex flex-column paginated-card"
    hide-default-footer
  >
    <template v-slot:loading>
      <v-overlay
        :value="config.fetching"
        absolute
        class="paginated-card__fetching"
        opacity="0.15"
      >
        <SyncLoader :color="loaderColor" />
      </v-overlay>
    </template>
    <template v-slot:no-data>
      <div id="data-iterator-no-data">
        <component
          :is="config.lastChild.componentName"
          v-if="config.lastChild"
        />
        <HelpWatermark :config="noDataMessage" v-else />
      </div>
    </template>
    <template v-slot:header>
      <v-row no-gutters justify="center">
        <FormattedText
          type="text-h6"
          color="textPrimary"
          :value="config.title"
        />
      </v-row>
    </template>
    <template v-slot:default="props">
      <transition-group
        id="data-iterator-container"
        appear
        name="slide-in"
        tag="div"
      >
        <v-row
          no-gutters
          justify="center"
          v-for="(item, index) in props.items"
          :key="'card-' + index"
          @click="onClickCard(item)"
        >
          <component
            :is="config.cardComponents[config.currentCardComponent].component"
            :data="item"
            :methods="
              config.cardComponents[config.currentCardComponent].methods
            "
            :index="index"
            :truncate="
              config.cardComponents[config.currentCardComponent].truncate
            "
            class="my-2"
          />
        </v-row>
        <v-row
          no-gutters
          key="card-new"
          justify="center"
          v-if="config.lastChild && props.items.length > 0 && isLastPage"
        >
          <v-col cols="12">
            <v-divider class="my-2" />
          </v-col>
          <component :is="config.lastChild.componentName" />
        </v-row>
      </transition-group>
    </template>
    <template v-slot:footer>
      <v-row
        no-gutters
        align="end"
        justify="center"
        class=" my-10"
        id="data-iterator-footer"
      >
        <div v-if="config.items.length > 0">
          <v-btn
            small
            dark
            rounded
            :color="isFirstPage ? 'accent' : 'primary'"
            class="mr-1"
            :disabled="isFirstPage"
            @click="backPage"
            v-track:click="{
              category: $route.name,
              screen: 'PaginatedColumns',
              name: 'Go to previous page',
            }"
          >
            <v-icon>mdi-chevron-left</v-icon>
          </v-btn>
          <v-btn
            small
            dark
            rounded
            :color="isLastPage ? 'accent' : 'primary'"
            class="ml-1"
            :disabled="isLastPage"
            @click="nextPage"
            v-track:click="{
              category: $route.name,
              screen: 'PaginatedColumns',
              name: 'Go to next page',
            }"
          >
            <v-icon>mdi-chevron-right</v-icon>
          </v-btn>
        </div>
      </v-row>
    </template>
  </v-data-iterator>
</template>

<script>
import { SyncLoader } from '@saeris/vue-spinners'
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { getObjectCopy } from '@/tools/data'

import FormattedText from '@/components/shared/FormattedText'
import VendorCard from '@/components/shared/VendorCard'
import HelpWatermark from '@/components/shared/HelpWatermark'
import AddCustomVendor from '@/components/VendorsView/VendorsList/AddCustomVendor'

import dark from '@/themes/dark'
import light from '@/themes/light'

export default {
  name: 'ColumnPaginatedCard',
  components: {
    FormattedText,
    VendorCard,
    SyncLoader,
    HelpWatermark,
    AddCustomVendor,
  },
  props: {
    config: {
      type: Object,
      required: true,
    },
    customSort: {
      type: Function,
      required: true,
    },
    sortDesc: {
      type: Boolean,
    },
  },
  data() {
    return {
      page: this.config.page,
      itemsPerColumn: this.config.itemsPerColumn,
      noDataMessage: this.config.noDataMessage,
      cardHeight: this.config.cardComponents[this.config.currentCardComponent]
        .cardHeight,
    }
  },
  computed: {
    ...mapState('app', ['windowSize']),
    numberOfPages() {
      return Math.ceil(this.config.items.length / this.itemsPerColumn)
    },
    isFirstPage() {
      return this.page === 1
    },
    isLastPage() {
      return this.page === this.numberOfPages
    },
    loaderColor() {
      return this.$vuetify.theme.dark ? dark.productLoader : light.productLoader
    },
  },
  methods: {
    itemsPerColumnDynamic() {
      const container = document.getElementById('data-iterator-container')
      const columnsContainer = document.getElementById('columns-container')
      const footer = document.getElementById('data-iterator-footer')
      const containerHeight = !isNil(container)
        ? parseInt(container.clientHeight, 0)
        : parseInt(columnsContainer.clientHeight) -
          parseInt(getComputedStyle(footer).marginTop, 0) -
          100
      return Math.trunc(containerHeight / this.cardHeight) - 1
    },
    onClickCard(item) {
      const cleanItem = getObjectCopy(item)
      this.clicks++
      if (this.clicks === 1) {
        var self = this
        this.timer = setTimeout(() => {
          self.clicks = 0
          this.config.cardComponents[
            this.config.currentCardComponent
          ].methods.onClick(cleanItem)
        }, 200)
      } else {
        clearTimeout(this.timer)
        this.clicks = 0
        this.config.cardComponents[
          this.config.currentCardComponent
        ].methods.onDblClick(cleanItem)
      }
    },
    nextPage() {
      if (this.page + 1 <= this.numberOfPages) this.page += 1
    },
    backPage() {
      if (this.page - 1 >= 1) this.page -= 1
    },
  },
  watch: {
    'windowSize.y': function(newValue, oldValue) {
      if (oldValue !== newValue) {
        setTimeout(() => {
          this.itemsPerColumn = this.itemsPerColumnDynamic()
        }, 100)
      }
    },
  },
  mounted() {
    setTimeout(() => {
      this.itemsPerColumn = this.itemsPerColumnDynamic()
    }, 100)
  },
}
</script>

<style lang="scss" scoped>
.paginated-card {
  background-color: var(--v-mainBackground-base) !important;
  height: 100%;
  overflow: hidden;
  .paginated-card__fetching {
    height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
  }
}

#data-iterator-container {
  height: 80%;
}
</style>
