import SingleTextFieldWidget from '@/components/shared/SingleTextFieldWidget'
import FrequencySelector from '@/components/VendorsView/VendorDetailDialog/FrequencySelector'

const setConfig = (state, methods) => ({
  state,
  methods,
  singleWidgets: [
    [
      {
        id: 'nameVendor',
        type: SingleTextFieldWidget,
        visible: state.vendor.supplierId === 0,
        value: state.vendor.name,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.vendorName'
        ),
        hint: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.vendorNameHint'
        ),
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue => {
          methods.updateSelectedVendor({
            field: 'name',
            value: newValue,
          })
        },
        onInputFinishEdit: () => {},
      },
      {
        id: 'legalId',
        type: SingleTextFieldWidget,
        value: state.vendor.tributaryId,
        visible: true,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.identification'
        ),
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue => {
          methods.updateSelectedVendor({
            field: 'tributaryId',
            value: newValue,
          })
        },
        onInputFinishEdit: () => {},
      },
      {
        id: 'sellerName',
        type: SingleTextFieldWidget,
        value: state.vendor.sellerName,
        visible: true,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.name'
        ),
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue => {
          methods.updateSelectedVendor({
            field: 'sellerName',
            value: newValue,
          })
        },
        onInputFinishEdit: () => {},
      },
      {
        id: 'sellerPhone',
        type: SingleTextFieldWidget,
        value: state.vendor.sellerPhone,
        visible: true,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.phone'
        ),
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: '',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? '-'
            : value.toString()
        },
        onInputChange: newValue => {
          methods.updateSelectedVendor({
            field: 'sellerPhone',
            value: newValue,
          })
        },
        onInputFinishEdit: () => {},
      },
      {
        id: 'daysSelector',
        type: FrequencySelector,
        label: 'vendorsView.dialogs.detail.fields.daysVisists',
        extraClasses: 'ml-4 mb-5',
        visible: true,
        value: state.vendor.frequency.split(','),
        onInputChange: newValue => {
          let freq = state.vendor.frequency.split(',')
          let newFreq = ['0', '0', '0', '0', '0', '0', '0']
          newFreq.push(freq[7])
          newFreq.push(freq[8])
          newValue.forEach(value => {
            newFreq[value] = '1'
          })
          methods.updateSelectedVendor({
            field: 'frequency',
            value: newFreq.toString(),
          })
        },
        onFinishEdit: () => {},
      },
      {
        id: 'debtLimit',
        type: SingleTextFieldWidget,
        value: state.vendor.debtLimit,
        valueTextColor: 'textPrimary',
        editTextColor: 'customerPrimary',
        label: methods.getTranslatedText(
          'vendorsView.dialogs.detail.fields.debtLimit'
        ),
        labelIcon: 'mdi-pencil',
        iconColor: 'accent',
        extraClasses: '',
        textFormatter: value => {
          return value === undefined || value === null || value.length < 1
            ? null
            : value.toString()
        },
        onInputChange: newValue => {
          methods.updateSelectedVendor({
            field: 'debtLimit',
            value: newValue > 0 ? newValue : 0,
          })
        },
        onInputFinishEdit: () => {},
      },
    ],
  ],
})

export default setConfig
