<template>
  <div class="d-flex flex-column">
    <FormattedText
      intl
      :value="label"
      type="text-subtitle-2"
      :class="!reverse ? 'label-padding' : ''"
    />
    <v-radio-group :row="row" v-model="value" @change="changeSelect">
      <v-radio
        v-for="item in data"
        :key="item.label"
        :label="item.label"
        :value="item.value"
      />
    </v-radio-group>
  </div>
</template>

<script>
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'RadioButtonGroupWidget',
  components: { FormattedText },
  props: {
    config: {
      type: Object,
      required: true,
    },
    values: {
      type: String,
      required: false,
    },
  },
  data() {
    return {
      label: this.config.label,
      reverse: this.config.reverse,
      data: this.config.data,
      row: this.config.rowOrientation,
    }
  },
  computed: {
    value: {
      get() {
        return this.values ? this.values : this.config.value
      },
      set(newValue) {
        return this.config.onInputChange(newValue)
      },
    },
  },
  methods: {
    changeSelect() {
      this.config.onInputFinishEdit()
    },
  },
}
</script>
