import { required, decimal, minValue, maxValue } from 'vuelidate/lib/validators'

import {
  formatNumberFromDbToCurrency,
  formatNumberFromDb,
} from '@/tools/numbersFormat'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.opened,
    icon: 'mdi-cash-refund',
    title: 'vendorsView.dialogs.settleDebtDialog.payDebt',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: ['vendorsView.dialogs.settleDebtDialog.message'],
    extraValuesMessages: [
      state.vendor.name,
      formatNumberFromDbToCurrency(state.vendor.debt),
    ],
    height: 300,
    maxWidth: 500,
    id: 'settle-debt-vendor-form',
    onClickCancel: () => {
      methods.track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'SettleDebtDialog',
        name: 'Close dialog',
      })
      methods.closeDialog()
    },
  },
  fields: [
    {
      id: 'settleGeneralDebtAmount',
      type: 'input',
      valueType: 'number',
      label: 'shared.amount',
      errorMessage: 'mainLayout.user.errorAmount',
      color: 'primaryColor',
      required: true,
      autofocus: true,
      validators: {
        required,
        decimal,
        minValue: minValue(0.1),
        maxValue: maxValue(formatNumberFromDb(state.vendor.debt)),
      },
    },
  ],
  multipleButtons: [
    {
      ref: 'cancelButton',
      color: 'accent',
      onClick: () => {
        methods.track({
          type: 'interaction',
          action: 'click',
          category: 'Vendors',
          screen: 'SettleDebtDialog',
          name: 'Close dialog',
        })
        methods.closeDialog()
      },
      text: 'shared.cancel',
    },
    {
      tooltip: {
        text: 'vendorsView.dialogs.settleDebtDialog.payExternalCashRegister',
      },
      ref: 'externalCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(true),
      text: 'vendorsView.dialogs.settleDebtDialog.externalCashRegister',
    },
    {
      tooltip: {
        text: 'vendorsView.dialogs.settleDebtDialog.payMainCashRegister',
      },
      ref: 'mainCashRegister',
      color: 'primary',
      onClick: () => methods.showInfoDialog(),
      text: 'vendorsView.dialogs.settleDebtDialog.mainCashRegister',
    },
  ],
  id: 'settle-debt-vendor-form',
})

export default setConfig
