<template>
  <ToolBar :config="componentConfig" />
</template>

<script>
import { values } from 'ramda'
import { mapActions } from 'vuex'

import vendorsViewActions from '@/store/vendorsView/actions.types'

import config from '@/components/VendorsView/VendorsToolbar/Filters/config'
import ToolBar from '@/components/shared/ToolBar'

export default {
  name: 'CustomersFilter',
  components: {
    ToolBar,
  },
  data() {
    return {
      config,
    }
  },
  computed: {
    componentConfig: function() {
      return config(
        {},
        {
          setVendorSearchTerm: this[vendorsViewActions.setVendorSearchTerm],
          setSupplierSearchTerm: this[vendorsViewActions.setSupplierSearchTerm],
        }
      )
    },
  },
  methods: {
    ...mapActions('vendorsView', values(vendorsViewActions)),
  },
}
</script>
