<template>
  <v-card flat color="cardBackgroundPrimary">
    <div class="pt-6 d-flex flex-column">
      <v-card class="pa-0 rounded-widget" color="cardBackgroundSecondary" flat>
        <div class="py-1 pl-5 pr-1 d-flex widget-title align-center">
          <v-icon color="accent">
            mdi-truck
          </v-icon>
          <FormattedText
            intl
            type="text-body-1"
            color="textOverBackground"
            value="vendorsView.dialogs.detail.title"
            class="pl-2 pt-1 pb-1"
            className="font-weight-bold"
          />
        </div>
        <v-container class="pa-0">
          <div class="d-flex flex-column pa-4">
            <div
              v-for="(row, index) in widgetConfig.singleWidgets"
              :key="index"
              class="mb-3"
            >
              <div class="d-flex justify-space-between">
                <div v-for="widget in row" :key="widget.id">
                  <component
                    :is="widget.type"
                    :config="widget"
                    :class="widget.extraClasses"
                  />
                </div>
              </div>
            </div>
          </div>
        </v-container>
      </v-card>
    </div>
  </v-card>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import VENDORS_DB_API_EVENTS from '@/config/events/databaseAPI/vendorsEvents'

import { getTranslatedText } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'

import vendorsActions from '@/store/vendors/actions.types'
import vendorsViewActions from '@/store/vendorsView/actions.types'

import setConfig from '@/components/VendorsView/VendorDetailDialog/DetailsTab/config'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'DetailsTab',
  components: { FormattedText },
  computed: {
    ...mapState('vendorsView', ['selectedVendor']),
    widgetConfig() {
      return setConfig(
        { vendor: this.selectedVendor },
        {
          getTranslatedText: this.getTranslatedText,
          context: this,
          updateSelectedVendor: this[
            vendorsViewActions.updateSelectedVendorField
          ],
          updateDatabase: this.editVendor,
        }
      )
    },
  },
  methods: {
    getTranslatedText,
    ...mapActions('vendors', [vendorsActions.editVendorField]),
    ...mapActions('vendorsView', [
      vendorsViewActions.updateSelectedVendorField,
    ]),
    editVendor(data) {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Vendors',
        screen: 'VendorDetails',
        name: `Save ${Object.keys(data.data)[0].replace('_', ' ')}`,
      })
      rendererEventsService.send(VENDORS_DB_API_EVENTS.channel, {
        event: VENDORS_DB_API_EVENTS.events.update.name,
        data,
      })
    },
  },
}
</script>

<style lang="scss" scoped>
.rounded-widget {
  border-radius: 8px;
  .widget-title {
    background-color: var(--v-accentLight-base);
  }
}
.field-width {
  width: 140px;
  max-width: 145px;
}
</style>
