<template>
  <v-card
    flat
    color="cardBackground"
    class="rounded-lg d-flex align-center vendor-card"
    :class="{ 'draft-vendor': !data.isSupplierAdded }"
  >
    <div class="image-section px-2">
      <v-img
        contain
        max-height="85"
        width="140"
        max-width="140"
        class="rounded-l-lg"
        :src="logoPath(data)"
      />
    </div>
    <div
      class="vendor-section py-2 px-4 d-flex w-full"
      :class="[
        data.isSupplierAdded
          ? 'flex-column'
          : 'flex-row justify-space-between align-center',
      ]"
    >
      <v-tooltip top color="accent">
        <template v-slot:activator="{ on, attrs }">
          <div v-bind="attrs" v-on="on">
            <FormattedText
              :type="data.isSupplierAdded ? 'text-subtitle-1' : 'text-h6'"
              :value="data.name"
              className="font-weight-bold"
              shorter
              :shorterValue="trucateLength"
              class="mb-2 line-clamp"
            />
          </div>
        </template>
        <span>{{ data.name }}</span>
      </v-tooltip>
      <div
        class="d-flex flex-row justify-space-between w-full"
        v-if="data.isSupplierAdded"
      >
        <v-tooltip top color="accent">
          <template v-slot:activator="{ on, attrs }">
            <div class="stat-widget pr-2" v-bind="attrs" v-on="on">
              <v-icon class="pr-1">
                mdi-package-variant-closed
              </v-icon>
              <span>{{ currentDraftPurchaseCost }}</span>
            </div>
          </template>
          <span>{{
            getTranslatedText('vendorsView.card.DraftPurchaseCost')
          }}</span>
        </v-tooltip>
        <v-tooltip top color="accent">
          <template v-slot:activator="{ on, attrs }">
            <div class="stat-widget pr-2" v-bind="attrs" v-on="on">
              <v-icon color="primary" class="pr-1">
                mdi-poll-box
              </v-icon>
              <b class="vendorDebt--text">{{ currentDebt }}</b>
            </div>
          </template>
          <span>{{
            getTranslatedText('vendorsView.dialogs.detail.debtToPay')
          }}</span>
        </v-tooltip>
      </div>
      <div v-else>
        <v-icon>mdi-plus-circle</v-icon>
      </div>
    </div>
  </v-card>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { getTranslatedText } from '@/tools/data'
import { formatNumberFromDbToCurrency } from '@/tools/numbersFormat'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'VendorCard',
  components: { FormattedText },
  props: {
    data: {
      type: Object,
      required: false,
    },
    methods: {
      type: Object,
    },
    truncate: {
      type: Object,
      default: null,
    },
  },
  computed: {
    ...mapState('app', {
      assetsPath: state => state.paths.assets,
    }),
    trucateLength() {
      switch (this.$vuetify.breakpoint.name) {
        case 'lg':
          return this.truncate.lg
        case 'xl':
          return this.truncate.xl
        default:
          return '50'
      }
    },
    currentDraftPurchaseCost() {
      if (!this.data.isSupplierAdded) return '-'
      const purchase = this.data.purchases.find(
        purchase => purchase.status === '1'
      )
      return !isNil(purchase)
        ? formatNumberFromDbToCurrency(purchase.cost)
        : '-'
    },
    currentDebt() {
      return this.data.isSupplierAdded
        ? formatNumberFromDbToCurrency(this.data.debt)
        : '-'
    },
  },
  methods: {
    getTranslatedText,
    logoPath(vendor) {
      const id = vendor.isSupplierAdded ? vendor.supplierId : vendor.id
      const logoSRC =
        vendor.hasLogo === 1
          ? `file://${this.assetsPath}/suppliers/supplier_${id}.png`
          : require(`@/assets/logos/Icono_PlayStore.svg`)
      return logoSRC
    },
  },
}
</script>

<style lang="scss" scoped>
.vendor-card {
  height: 95px;
  max-height: 95px;
  width: 100%;
  max-width: 400px;
  cursor: pointer;
}
.w-full {
  width: 100%;
}
.draft-vendor {
  filter: grayscale(1);
  opacity: 0.5;
}
.line-clamp {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
</style>
