const config = (state, methods) => ({
  state,
  methods,
  groups: [
    {
      id: 'operations-group-01',
      controls: [
        {
          id: 'help-dropdown-control',
          type: 'buttonDropdown',
          label: 'productsView.toolbar.buttons.help',
          icon: 'mdi-school',
          color: 'help',
          textColor: 'textPrimary',
          items: state.videos,
          listItemType: 'VideoListItem',
        },
        {
          id: 'scan-button-control',
          type: 'button',
          label:
            state.isScannerActive === true
              ? 'productsView.toolbar.buttons.keyboard'
              : 'productsView.toolbar.buttons.scan',
          icon:
            state.isScannerActive === true
              ? 'mdi-keyboard-outline'
              : 'mdi-barcode-scan',
          color: 'accent',
          onClick: () => console.log('Scanner filter button pressed'),
        },
      ],
    },
  ],
})

export default config
