<template>
  <v-dialog
    v-model="vendorDetailDialog.isOpen"
    :overlay-opacity="0.15"
    max-width="640px"
    :hide-overlay="tourEnabled"
    :content-class="
      tourEnabled ? 'below-tour default-dialog' : 'default-dialog'
    "
    :persistent="tourEnabled"
    @click:outside="onClickCancel"
  >
    <v-card
      flat
      class="view-section"
      :height="670"
      color="cardBackgroundPrimary"
      id="vendor-detail"
    >
      <Header />
      <v-card-text>
        <Tabs
          :tabs="tabs"
          backgroundColor="cardBackgroundPrimary"
          textColor="accent"
          track-screen="VendorDetails"
        />
      </v-card-text>
      <Footer />
    </v-card>
  </v-dialog>
</template>

<script>
import { values, isNil } from 'ramda'
import { mapActions, mapState } from 'vuex'

import { testMode } from '@/config/env'
import { cashOperation } from '@/config/storeMapper'

import CASH_OPERATIONS_DB_API_EVENTS from '@/config/events/databaseAPI/cashOperationsEvents'
import ENTITIES_EVENTS from '@/config/events/databaseAPI/entitiesEvents'
import ADD_PRODUCT_EVENTS from '@/config/events/addProduct'
import PURCHASES_DB_API_EVENTS from '@/config/events/databaseAPI/purchaseOrderEvents'

import { getTranslatedText, mapStoreObject } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import vendorsViewActions from '@/store/vendorsView/actions.types'
import operationsViewActions from '@/store/operationsView/actions.types'
import productsActions from '@/store/products/actions.types'

import Header from '@/components/VendorsView/VendorDetailDialog/Header'
import DetailsTab from '@/components/VendorsView/VendorDetailDialog/DetailsTab'
import LastOrdersTab from '@/components/VendorsView/VendorDetailDialog/LastOrdersTab'
import Tabs from '@/components/shared/Tabs'
import Footer from '@/components/VendorsView/VendorDetailDialog/Footer'

export default {
  name: 'VendorDetailDetail',
  components: { Header, Tabs, Footer },
  data() {
    return {
      vendor: null,
      tabs: [
        {
          id: 0,
          name: this.getTranslatedText(
            'vendorsView.dialogs.detail.tabs.lastOrders'
          ),
          icon: 'mdi-cart',
          component: LastOrdersTab,
        },
        {
          id: 1,
          name: this.getTranslatedText(
            'vendorsView.dialogs.detail.tabs.detail'
          ),
          icon: 'mdi-clipboard-check',
          component: DetailsTab,
        },
      ],
    }
  },
  computed: {
    ...mapState('vendorsView', {
      selectedVendor: state => state.selectedVendor,
      vendorDetailDialog: state => state.vendorDetailDialog,
      purchase: state => state.repeatPurchaseConfirmDialog.purchaseSelected,
      isOpen: state => state.repeatPurchaseConfirmDialog.isOpen,
    }),
    ...mapState('vendors', {
      vendors: state => state.data.vendors,
    }),
    ...mapState('purchasesView', ['tourEnabled']),
  },
  methods: {
    ...mapActions('vendorsView', values(vendorsViewActions)),
    ...mapActions('operationsView', [
      operationsViewActions.setOperationDetailDialogStatus,
    ]),
    ...mapActions('products', [
      productsActions.addProductFromMLP,
      productsActions.removeProductFromMlpData,
    ]),
    getTranslatedText,
    onClickCancel() {
      this.closeDialog()
    },
    closeDialog() {
      if (this.tourEnabled) this.$root.$emit('vendor-cancel-tour')
      this[vendorsViewActions.toggleVendorDetailDialog]()
      this[vendorsViewActions.setSelectedSupplier](null)
      this[vendorsViewActions.setSelectedVendor](null)
    },
    onProductsAdded(data) {
      const { newProducts, productsNotInMLP } = data
      const oldPurchaseItems = this.purchase.items.filter(
        purchaseItem => !productsNotInMLP.includes(purchaseItem.product_name)
      )
      let newPurchaseItems = []
      oldPurchaseItems.forEach(oldPurchaseItem => {
        const product = newProducts.find(
          product => product.name === oldPurchaseItem.product_name
        )
        if (isNil(product)) {
          newPurchaseItems.push(oldPurchaseItem)
          return
        }
        this[productsActions.addProductFromMLP]({
          newProduct: product,
          currentView: 'vendorsView',
        })
        this[productsActions.removeProductFromMlpData](product)
        const newPurchaseItem = {
          ...oldPurchaseItem,
          product_id: product.id,
          product_stock: 0,
        }
        newPurchaseItems.push(newPurchaseItem)
      })
      this.purchase.items = newPurchaseItems
    },
    cashOperationsListener(event, payload) {
      const events = CASH_OPERATIONS_DB_API_EVENTS.events
      const replies = {
        [events.getByOperationTypeAndRelatedId.replies.success]: () => {
          rendererEventsService.send(CASH_OPERATIONS_DB_API_EVENTS.channel, {
            event: CASH_OPERATIONS_DB_API_EVENTS.events.getOperationDetail.name,
            data: {
              operation: mapStoreObject(payload.data, cashOperation),
              vendors: this.vendors,
            },
          })
        },
        [events.getOperationDetail.replies.success]: () => {
          this[operationsViewActions.setOperationDetailDialogStatus]({
            isOpen: true,
            operationSelected: payload.data,
          })
        },
        [events.getByOperationTypeAndRelatedId.replies.error]: () =>
          notificationsService.showError(
            payload.data.errorMsg,
            this.$vuetify.lang
          ),
        [events.getOperationDetail.replies.error]: () =>
          notificationsService.showError(
            'notification.operations.cantOpenDetail',
            this.$vuetify.lang
          ),
        [events.undoOperation.replies.success]: () => {
          rendererEventsService.send(ENTITIES_EVENTS.channel, {
            event: ENTITIES_EVENTS.events.getAllByEntities.name,
            data: {
              entitiesToGet: ['vendors', 'purchaseOrder', 'payables'],
              replyName: 'fetchVendors',
            },
          })
          this.closeDialog()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    async productAddedListener(event, payload) {
      const productEventsReplies =
        ADD_PRODUCT_EVENTS.events.addProductsFromMLP.replies
      const replies = {
        [productEventsReplies.success]: () => {
          this.onProductsAdded(payload.data)
          this.$loading.show('createPurchase')
          rendererEventsService.send(PURCHASES_DB_API_EVENTS.channel, {
            event: PURCHASES_DB_API_EVENTS.events.repeatPurchase.name,
            data: {
              oldPurchase: this.purchase,
              purchaseData: {
                vendorId: this.purchase.vendor_id,
                status: 1,
                source: 1,
                promotion: 0,
                items: [],
                cost: this.purchase.cost,
              },
            },
          })
          this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog]()
        },
        [productEventsReplies.error]: () => {
          notificationsService.showError(
            'notification.vendors.purchaseError',
            this.$vuetify.lang
          )
          this[vendorsViewActions.toggleRepeatPurchaseConfirmDialog]()
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
  },
  created() {
    if (testMode) return
    rendererEventsService.subscribe(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationsListener
    )
    rendererEventsService.subscribe(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.productAddedListener
    )
    if (!isNil(this.selectedVendor)) {
      this.vendor = this.selectedVendor
      return
    }
    this.vendor = this.selectedSupplier
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      CASH_OPERATIONS_DB_API_EVENTS.replyChannel,
      this.cashOperationsListener
    )
    rendererEventsService.removeListener(
      ADD_PRODUCT_EVENTS.replyChannel,
      this.productAddedListener
    )
  },
}
</script>
