<template>
  <v-card-title>
    <div>
      <FormattedText
        type="text-h4"
        className="vendor-name"
        class="vendor-name-padding"
      >
        {{ selectedVendor ? selectedVendor.name : null }}
      </FormattedText>
      <FormattedText
        className="font-italic"
        color="textSecondary"
        type="text-body-1"
        class="vendor-name"
      >
        {{ selectedVendor ? selectedVendor.tributaryId : '' }}
      </FormattedText>
      <!-- TODO implement with purchase feature (maybe)  -->
      <!-- <div class="d-flex" v-if="selectedSupplier == null">
        <FormattedText
          intl
          value="vendorsView.dialogs.detail.nextDelivery"
          type="text-h6"
          className="vendor-name"
        >
        </FormattedText>
        <FormattedText type="text-h6" className="vendor-name">
          {{ selectedVendor ? deliveryDate : null }}
        </FormattedText>
      </div> -->
    </div>
    <v-avatar width="100px" height="80px" rounded="lg">
      <v-img contain :src="logoPath" />
    </v-avatar>
  </v-card-title>
</template>

<script>
import { mapState } from 'vuex'
import { isNil } from 'ramda'

import { formatDate } from '@/tools/dates'

import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'Header',
  components: { FormattedText },
  computed: {
    ...mapState('vendorsView', {
      selectedVendor: state => state.selectedVendor,
      selectedSupplier: state => state.selectedSupplier,
    }),
    ...mapState('app', {
      assetsPath: state => state.paths.assets,
    }),
    logoPath() {
      const vendorId = !isNil(this.selectedVendor.supplierId)
        ? this.selectedVendor.supplierId
        : this.selectedVendor.id
      const logoSRC =
        this.selectedVendor.hasLogo === 1
          ? `file://${this.assetsPath}/suppliers/supplier_${vendorId}.png`
          : require(`@/assets/logos/Icono_PlayStore.svg`)
      return logoSRC
    },
    deliveryDate() {
      const date = this.selectedVendor.frequency.split(',')[8]
      return formatDate(date)
    },
  },
}
</script>
